#include <stdio.h>

int next_factorial(void) {
    static int n = 0, product = 1;
    product *= ++n;
    return product;
}

int main(void) {
    for (int i = 1; i <= 5; i++) printf("%d%c", next_factorial(), i == 5 ? '\n' : ' ');
    return 0;
}
